package ae;

import static org.junit.jupiter.api.Assertions.*;

import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import org.junit.jupiter.api.Test;

class ResultTest {
    @Test
    void mapTransformsOkOnly() {
        Result<Integer, String> ok = new Result.Ok<>(2);
        Result<Integer, String> err = new Result.Err<>("bad");
        assertEquals(new Result.Ok<Integer, String>(4), ok.map(x -> x * 2));
        assertEquals(new Result.Err<Integer, String>("bad"), err.map(x -> x * 2));
    }

    @Test
    void flatMapChainsAndShortCircuits() {
        Result<Integer, String> ok = new Result.Ok<>(10);
        Result<Integer, String> r = ok.flatMap(x -> x > 5 ? new Result.Err<Integer, String>("big") : new Result.Ok<>(x));
        assertEquals(new Result.Err<Integer, String>("big"), r);
        int[] calls = {0};
        new Result.Err<Integer, String>("e").flatMap(x -> { calls[0]++; return new Result.Ok<Integer, String>(x); });
        assertEquals(0, calls[0]);
    }

    @Test
    void mapErrorAndFallbacks() {
        Result<Integer, String> err = new Result.Err<>("abc");
        assertEquals(new Result.Err<Integer, Integer>(3), err.mapError(String::length));
        assertEquals(7, err.orElse(7));
        assertEquals(3, err.getOrElseGet(String::length));
        assertEquals(Optional.empty(), err.toOptional());
        assertEquals(Optional.of(1), new Result.Ok<Integer, String>(1).toOptional());
        assertTrue(new Result.Ok<Integer, String>(1).isOk());
        assertFalse(err.isOk());
    }

    @Test
    void ofCapturesRuntimeException() {
        Result<Integer, RuntimeException> r = Result.of(() -> Integer.parseInt("x"));
        assertFalse(r.isOk());
        assertInstanceOf(NumberFormatException.class, ((Result.Err<Integer, RuntimeException>) r).error());
        assertEquals(5, Result.of(() -> 5).orElse(0));
    }

    @Test
    void sequenceCollectsOrFailsFirst() {
        List<Result<Integer, String>> good = List.of(new Result.Ok<>(1), new Result.Ok<>(2));
        assertEquals(new Result.Ok<List<Integer>, String>(List.of(1, 2)), Result.sequence(good));
        List<Result<Integer, String>> bad = List.of(new Result.Ok<>(1), new Result.Err<>("a"), new Result.Err<>("b"));
        assertEquals(new Result.Err<List<Integer>, String>("a"), Result.sequence(bad));
        assertEquals(new Result.Ok<List<Integer>, String>(List.of()), Result.sequence(List.<Result<Integer, String>>of()));
    }

    @Test
    void sequenceResultIsImmutableAndDetached() {
        List<Result<Integer, String>> src = new ArrayList<>(List.of(new Result.Ok<>(1)));
        Result<List<Integer>, String> r = Result.sequence(src);
        src.add(new Result.Ok<>(2));
        List<Integer> out = ((Result.Ok<List<Integer>, String>) r).value();
        assertEquals(List.of(1), out);
        assertThrows(UnsupportedOperationException.class, () -> out.add(3));
    }

    @Test
    void nullsRejected() {
        assertThrows(NullPointerException.class, () -> new Result.Ok<String, String>(null));
        assertThrows(NullPointerException.class, () -> new Result.Err<String, String>(null));
    }
}

package ae;

import static org.junit.jupiter.api.Assertions.*;

import java.util.*;
import org.junit.jupiter.api.Test;

class GenericsTest {
    @Test
    void maxOfComparables() {
        assertEquals(Optional.of(9), Generics.max(List.of(3, 9, 4)));
        assertEquals(Optional.empty(), Generics.max(List.<Integer>of()));
        assertEquals(Optional.of("pear"), Generics.max(Set.of("pear", "apple")));
    }

    @Test
    void maxSupportsSubtypeOfComparableSupertype() {
        // java.sql.Timestamp-like case: Sub extends Base implements Comparable<Base>
        List<Sub> subs = List.of(new Sub(1), new Sub(5), new Sub(3));
        assertEquals(5, Generics.max(subs).orElseThrow().n);
    }

    static class Base implements Comparable<Base> {
        final int n;
        Base(int n) { this.n = n; }
        public int compareTo(Base o) { return Integer.compare(n, o.n); }
    }
    static class Sub extends Base { Sub(int n) { super(n); } }

    @Test
    void copyIntoWidensDestination() {
        List<Number> dst = new ArrayList<>(List.of(0.5));
        Generics.<Integer>copyInto(dst, List.of(1, 2));
        assertEquals(List.of(0.5, 1, 2), dst);
    }

    @Test
    void sumMixedNumbers() {
        assertEquals(6.5, Generics.sum(List.of(1, 2.5, 3L)), 1e-9);
        assertEquals(0.0, Generics.sum(List.of()), 0.0);
    }

    @Test
    void keyOfMaxPicksFirstOnTie() {
        Map<String, Integer> m = new LinkedHashMap<>();
        m.put("a", 3);
        m.put("b", 7);
        m.put("c", 7);
        assertEquals(Optional.of("b"), Generics.keyOfMax(m));
        assertEquals(Optional.empty(), Generics.keyOfMax(new HashMap<String, Integer>()));
    }
}

package ae;

import static org.junit.jupiter.api.Assertions.*;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

class SeverityTest {
    @ParameterizedTest
    @CsvSource({"low,LOW", "  Medium ,MEDIUM", "HIGH,HIGH", "critical,CRITICAL"})
    void parsesCaseInsensitively(String in, Severity expected) {
        assertEquals(new Result.Ok<Severity, String>(expected), Severity.parse(in));
    }

    @Test
    void parseFailureDescribesInput() {
        assertEquals(new Result.Err<Severity, String>("unknown severity: 'nope'"), Severity.parse("nope"));
        assertFalse(Severity.parse("").isOk());
        assertThrows(NullPointerException.class, () -> Severity.parse(null));
    }

    @Test
    void weightsAreIncreasing() {
        assertEquals(1, Severity.LOW.weight());
        assertEquals(2, Severity.MEDIUM.weight());
        assertEquals(4, Severity.HIGH.weight());
        assertEquals(8, Severity.CRITICAL.weight());
    }

    @Test
    void atLeastUsesOrder() {
        assertTrue(Severity.HIGH.atLeast(Severity.MEDIUM));
        assertTrue(Severity.HIGH.atLeast(Severity.HIGH));
        assertFalse(Severity.LOW.atLeast(Severity.CRITICAL));
    }

    @Test
    void parseThenSequence() {
        var r = Result.sequence(java.util.List.of(Severity.parse("low"), Severity.parse("high")));
        assertEquals(new Result.Ok<java.util.List<Severity>, String>(java.util.List.of(Severity.LOW, Severity.HIGH)), r);
    }
}
